import{_ as e,o as t,c as r,a0 as o}from"./chunks/framework.BXmxXpv-.js";const _=JSON.parse('{"title":"联系我们","titleTemplate":"智能计算系统实验室","description":"联系电子科技大学智能计算系统实验室，咨询研究生招生、科研合作与实验室事务。","frontmatter":{"title":"联系我们","titleTemplate":"智能计算系统实验室","description":"联系电子科技大学智能计算系统实验室，咨询研究生招生、科研合作与实验室事务。","outline":false,"aside":false},"headers":[],"relativePath":"zh/contact.md","filePath":"zh/contact.md","lastUpdated":1783582817000}'),l={name:"zh/contact.md"};function i(n,a,c,h,p,s){return t(),r("div",null,[...a[0]||(a[0]=[o('<h1 id="联系我们" tabindex="-1">联系我们 <a class="header-anchor" href="#联系我们" aria-label="Permalink to &quot;联系我们&quot;">​</a></h1><h2 id="公共邮箱" tabindex="-1">公共邮箱 <a class="header-anchor" href="#公共邮箱" aria-label="Permalink to &quot;公共邮箱&quot;">​</a></h2><p>一般事务请联系公共邮箱：<a href="mailto:public@nise.ac.cn" target="_blank" rel="noreferrer">public@nise.ac.cn</a>。</p><p>如需联系具体人员，请参考<a href="/zh/people">人员页</a>。</p><h2 id="招生咨询" tabindex="-1">招生咨询 <a class="header-anchor" href="#招生咨询" aria-label="Permalink to &quot;招生咨询&quot;">​</a></h2><p>实验室长期欢迎对智能计算系统、物联网、无线嵌入式系统、边缘智能与系统安全等方向感兴趣的硕士研究生和博士研究生加入。</p><p>有意申请者可通过公共邮箱联系，也可参考<a href="/zh/people#导师">人员页导师栏</a>联系相关导师。来信请简要说明研究兴趣，并附上个人简历、成绩单，以及代表性项目、论文或代码链接等材料。</p><h2 id="合作交流" tabindex="-1">合作交流 <a class="header-anchor" href="#合作交流" aria-label="Permalink to &quot;合作交流&quot;">​</a></h2><p>欢迎高校、科研机构和企业围绕科研合作、项目合作、学生联合培养和系统原型验证等事项联系实验室。相关合作意向可通过公共邮箱发送，请简要说明合作背景、目标方向和预期形式。</p><h2 id="地址" tabindex="-1">地址 <a class="header-anchor" href="#地址" aria-label="Permalink to &quot;地址&quot;">​</a></h2><p>中国四川省成都市高新西区电子科技大学清水河校区四号科研楼。</p><p>来访请提前通过邮件预约。</p>',12)])])}const f=e(l,[["render",i]]);export{_ as __pageData,f as default};
